#include "PianoRoll.h"
namespace{ const juce::Colour kBg{0xff1b232b},kOrange{0xffe5953d},kRuler{0xff121820};
 bool isBlackKey(int m){ int p=pauta::mod12(m); return p==1||p==3||p==6||p==8||p==10; }
 juce::String midiName(float m){ int r=(int)std::lround(m); int c=(int)std::lround((m-r)*100.f); juce::String s=juce::String(pauta::noteNames()[pauta::mod12(r)])+juce::String(r/12-1); if(c!=0) s<<(c>0?" +":" ")<<c<<"c"; return s; } }
PianoRoll::PianoRoll(LaPautaTuneProcessor& p):proc(p){ setWantsKeyboardFocus(true); addAndMakeVisible(hBar); addAndMakeVisible(vBar); hBar.addListener(this); vBar.addListener(this); hBar.setAutoHide(false); vBar.setAutoHide(false); }
void PianoRoll::setTool(Tool t){ tool=t; cutHoverIndex=-1; setMouseCursor(t==Tool::cut?juce::MouseCursor::CrosshairCursor:t==Tool::time?juce::MouseCursor::LeftRightResizeCursor:juce::MouseCursor::UpDownResizeCursor); repaint(); }
double PianoRoll::totalSeconds() const { return proc.hasProject()?(double)proc.getNumSourceSamples()/sr():10.0; }
juce::Rectangle<int> PianoRoll::contentArea() const { return {keyW,rulerH,std::max(1,getWidth()-keyW-barSize),std::max(1,getHeight()-rulerH-barSize)}; }
int PianoRoll::visibleRows() const { return std::max(1,contentArea().getHeight()/rowH); }
void PianoRoll::clampScroll(){
 double visSec=contentArea().getWidth()/pps; scrollX=juce::jlimit(0.0,std::max(0.0,totalSeconds()+2.0-visSec),scrollX);
 // CORREGIDO: min y max en orden correcto
 double lo=(double)(midiLo+visibleRows()); double hi=(double)(midiHi+1);
 if(lo>hi) lo=hi; topMidi=std::round(juce::jlimit(lo,hi,topMidi));
}
void PianoRoll::updateScrollbars(){ auto c=contentArea(); double vis=c.getWidth()/pps; hBar.setRangeLimits(0,std::max(totalSeconds()+2.0,vis)); hBar.setCurrentRange(scrollX,vis,juce::dontSendNotification); vBar.setRangeLimits(0,(double)(midiHi-midiLo+1)); vBar.setCurrentRange((double)(midiHi+1)-topMidi,(double)visibleRows(),juce::dontSendNotification); }
void PianoRoll::scrollBarMoved(juce::ScrollBar* b,double s){ if(b==&hBar) scrollX=s; else topMidi=(double)(midiHi+1)-s; clampScroll(); repaint(); }
void PianoRoll::resized(){ hBar.setBounds(keyW,getHeight()-barSize,std::max(1,getWidth()-keyW-barSize),barSize); vBar.setBounds(getWidth()-barSize,rulerH,barSize,std::max(1,getHeight()-rulerH-barSize)); clampScroll(); updateScrollbars(); }
void PianoRoll::setPixelsPerSecond(double v,double ax){ v=juce::jlimit(15.0,1500.0,v); double a=ax>=0?ax:(double)keyW+contentArea().getWidth()*0.5; double tA=(a-keyW)/pps+scrollX; pps=v; scrollX=tA-(a-keyW)/pps; clampScroll(); updateScrollbars(); repaint(); if(onZoomChanged) onZoomChanged(pps); }
void PianoRoll::setPlayheadSeconds(double s){ if(std::abs(s-playheadSec)>1e-4){ playheadSec=s; repaint(); } }
void PianoRoll::projectChanged(){ int n=proc.getNumSourceSamples(); if(n!=lastProjectSamples||proc.getSourceSampleRate()!=lastProjectRate){ lastProjectSamples=n; lastProjectRate=proc.getSourceSampleRate(); if(n>0){ double dur=totalSeconds(); pps=juce::jlimit(40.0,200.0,contentArea().getWidth()/std::max(0.5,dur)); scrollX=0; std::vector<float> m; for(auto &nt:proc.getNotes()) m.push_back(nt.detectedMidi); double centre=60; if(!m.empty()){ std::sort(m.begin(),m.end()); centre=m[m.size()/2]; } topMidi=std::round(centre+visibleRows()*0.5); clampScroll(); updateScrollbars(); if(onZoomChanged) onZoomChanged(pps); } } repaint(); }
double PianoRoll::gridSeconds() const { double div=LaPautaTuneProcessor::gridDivision(proc.gridIndex); if(div<=0) return 0; double beat=60.0/std::max(20.0,proc.bpm.load()); return beat*4.0/div; }
double PianoRoll::snapTimelineSample(double s) const { double g=gridSeconds()*sr(); if(g<1) return s; return std::round(s/g)*g; }
juce::Rectangle<float> PianoRoll::noteRect(const pauta::Note& n) const { float x0=xOfSample((double)n.start+n.shift),x1=xOfSample((double)n.end+n.shift); float h=(float)rowH-2.f; return {x0,yOfMidi(n.targetMidi)-h*0.5f,std::max(3.f,x1-x0),h}; }
int PianoRoll::hitTest(juce::Point<float> p) const { auto c=contentArea().toFloat(); if(!c.contains(p)) return -1; auto &notes=proc.getNotes(); for(int i=(int)notes.size()-1;i>=0;--i) if(noteRect(notes[i]).expanded(0,2).contains(p)) return i; return -1; }
void PianoRoll::paint(juce::Graphics& g){ g.fillAll(kBg); auto content=contentArea(); { juce::Graphics::ScopedSaveState ss(g); g.reduceClipRegion(content); drawRows(g,content); drawGrid(g,content); drawNotes(g,content); if(tool==Tool::cut&&cutHoverIndex>=0&&cutHoverIndex<(int)proc.getNotes().size()){ auto r=noteRect(proc.getNotes()[cutHoverIndex]); float x=xOfSample(cutHoverSample); g.setColour(juce::Colours::white); g.drawLine(x,r.getY()-4,x,r.getBottom()+4,1.5f); } float px=xOfSeconds(playheadSec); if(px>=(float)keyW&&px<=(float)content.getRight()){ g.setColour(juce::Colour(0xffff5a3c)); g.drawVerticalLine((int)px,(float)rulerH,(float)getHeight()); } if(!proc.hasProject()){ g.setColour(juce::Colours::white.withAlpha(0.45f)); g.setFont(juce::FontOptions(18.f)); g.drawFittedText(proc.isLoading()?"Analizando la voz...":"Arrastra una voz aqui o pulsa Cargar voz",content,juce::Justification::centred,2); } } drawKeys(g); drawRuler(g); }
void PianoRoll::drawRows(juce::Graphics& g,juce::Rectangle<int> content){ auto mask=proc.getScaleMask(); bool lock=proc.lockScale; for(int m=midiLo;m<=midiHi;m++){ int y=(int)std::lround(yTopOfRow(m)); if(y+rowH<content.getY()||y>content.getBottom()) continue; bool in=pauta::isInScale(m,mask); juce::Colour c=isBlackKey(m)?juce::Colour(0xff18202a):juce::Colour(0xff202a35); if(in) c=c.brighter(0.25f); if(pauta::mod12(m)==proc.key) c=c.interpolatedWith(kOrange,0.16f); g.setColour(c); g.fillRect(content.getX(),y,content.getWidth(),rowH); if(lock&&!in){ g.setColour(juce::Colour(0xb00a0e13)); g.fillRect(content.getX(),y,content.getWidth(),rowH); g.setColour(juce::Colour(0x1fffffff)); for(int x=content.getX()-rowH;x<content.getRight();x+=9) g.drawLine((float)x,(float)(y+rowH),(float)(x+rowH),(float)y,1.f); } g.setColour(pauta::mod12(m)==0?juce::Colour(0x44ffffff):juce::Colour(0x14ffffff)); g.drawHorizontalLine(y+rowH-1,(float)content.getX(),(float)content.getRight()); } }
void PianoRoll::drawGrid(juce::Graphics& g,juce::Rectangle<int> content){ double beat=60.0/std::max(20.0,proc.bpm.load()); double bar=beat*4; double step=gridSeconds()>0?gridSeconds():beat; while(step*pps<6) step*=2; double t0=scrollX,t1=scrollX+content.getWidth()/pps; auto k0=(long long)std::floor(t0/step); for(long long k=k0;(double)k*step<=t1;k++){ double t=(double)k*step; float x=xOfSeconds(t); double nb=t/bar,nbt=t/beat; bool isBar=std::abs(nb-std::round(nb))<1e-6; bool isBeat=std::abs(nbt-std::round(nbt))<1e-6; g.setColour(isBar?juce::Colour(0x66ffffff):isBeat?juce::Colour(0x34ffffff):juce::Colour(0x16ffffff)); g.drawVerticalLine((int)x,(float)content.getY(),(float)content.getBottom()); } }
void PianoRoll::drawNotes(juce::Graphics& g,juce::Rectangle<int> content){ auto &notes=proc.getNotes(); auto &peaks=proc.getPeaks(); auto mask=proc.getScaleMask(); for(auto &n:notes){ auto r=noteRect(n); if(r.getRight()<content.getX()||r.getX()>content.getRight()||r.getBottom()<content.getY()||r.getY()>content.getBottom()) continue; if(std::abs(n.targetMidi-n.detectedMidi)>0.05f||n.shift!=0){ auto ghost=r; ghost.setY(yOfMidi(n.detectedMidi)-r.getHeight()*0.5f); ghost.setX(xOfSample((double)n.start)); ghost.setWidth(std::max(3.f,xOfSample((double)n.end)-ghost.getX())); g.setColour(kOrange.withAlpha(0.28f)); g.drawRoundedRectangle(ghost,2.f,1.f); } g.setColour(n.selected?juce::Colour(0xff5b7690):juce::Colour(0xff384a5b)); g.fillRoundedRectangle(r,3.f); if(!peaks.empty()){ int xa=std::max((int)std::floor(r.getX()),content.getX()), xb=std::min((int)std::ceil(r.getRight()),content.getRight()); float cy=r.getCentreY(), half=r.getHeight()*0.5f-1.5f; g.setColour(juce::Colour(0xffdbe2e8)); for(int x=xa;x<xb;x++){ double sA=sampleOfX((double)x)-n.shift, sB=sampleOfX((double)x+1)-n.shift; if(sB<0) continue; size_t b0=(size_t)std::max(0.0,sA/LaPautaTuneProcessor::peakBlock); size_t b1=(size_t)std::max(0.0,sB/LaPautaTuneProcessor::peakBlock); if(b0>=peaks.size()) continue; b1=std::min(b1,peaks.size()-1); float m=0; for(size_t b=b0;b<=b1;b++) m=std::max(m,peaks[b]); float a=std::sqrt(m)*half; g.drawVerticalLine(x,cy-a,cy+a+1.f); } } bool out=proc.lockScale&&!pauta::isInScale((int)std::lround(n.targetMidi),mask); g.setColour(n.selected?juce::Colours::white:out?juce::Colour(0xffd9534f):kOrange); g.drawRoundedRectangle(r,3.f,n.selected?2.f:1.4f); if(dragging&&n.selected){ g.setColour(juce::Colours::white); g.setFont(juce::FontOptions(12.f,juce::Font::bold)); g.drawText(midiName(n.targetMidi),(int)r.getX(),(int)r.getY()-15,80,14,juce::Justification::left); } } }
void PianoRoll::drawKeys(juce::Graphics& g){ auto mask=proc.getScaleMask(); auto keys=juce::Rectangle<int>(0,rulerH,keyW,contentArea().getHeight()); juce::Graphics::ScopedSaveState ss(g); g.reduceClipRegion(keys); g.fillAll(juce::Colour(0xff10151b)); for(int m=midiLo;m<=midiHi;m++){ int y=(int)std::lround(yTopOfRow(m)); if(y+rowH<rulerH||y>getHeight()) continue; g.setColour(juce::Colour(0xffe6e9ec)); g.fillRect(0,y,keyW,rowH); if(isBlackKey(m)){ g.setColour(juce::Colour(0xff1a1d21)); g.fillRect(0,y+1,(int)(keyW*0.64f),rowH-2); } g.setColour(juce::Colour(0xff8a9199)); g.drawHorizontalLine(y+rowH-1,0,(float)keyW); if(pauta::isInScale(m,mask)){ g.setColour(pauta::mod12(m)==proc.key?kOrange:juce::Colour(0xff3fb6d6)); g.fillEllipse((float)keyW-10.f,(float)y+(float)rowH*0.5f-3.f,6.f,6.f); } if(pauta::mod12(m)==0){ g.setColour(juce::Colour(0xff222831)); g.setFont(juce::FontOptions(11.f,juce::Font::bold)); g.drawText("C"+juce::String(m/12-1),3,y,keyW-14,rowH,juce::Justification::centredLeft); } } }
void PianoRoll::drawRuler(juce::Graphics& g){ juce::Graphics::ScopedSaveState ss(g); g.reduceClipRegion(keyW,0,getWidth()-keyW,rulerH); g.fillAll(kRuler); double bar=60.0/std::max(20.0,proc.bpm.load())*4.0; double t1=scrollX+(getWidth()-keyW)/pps; auto k0=(long long)std::floor(scrollX/bar); g.setFont(juce::FontOptions(12.f)); for(long long k=k0;(double)k*bar<=t1;k++){ float x=xOfSeconds((double)k*bar); g.setColour(juce::Colour(0x88ffffff)); g.drawVerticalLine((int)x,4.f,(float)rulerH); g.setColour(juce::Colour(0xffc9d1d9)); g.drawText(juce::String(k+1),(int)x+4,0,40,rulerH,juce::Justification::centredLeft); } float px=xOfSeconds(playheadSec); if(px>=(float)keyW){ juce::Path tri; tri.addTriangle(px-5,2,px+5,2,px,11); g.setColour(juce::Colour(0xffff5a3c)); g.fillPath(tri); } g.setColour(juce::Colour(0xff000000).withAlpha(0.5f)); g.drawHorizontalLine(rulerH-1,(float)keyW,(float)getWidth()); }
void PianoRoll::mouseDown(const juce::MouseEvent& e){ grabKeyboardFocus(); dragging=false; if(e.x<keyW) return; if(e.y<rulerH){ proc.setPlayPositionSeconds(std::max(0.0,sampleOfX((double)e.x)/sr())); return; } if(!proc.hasProject()) return; auto &notes=proc.getNotes(); int idx=hitTest(e.position); if(tool==Tool::cut){ if(idx>=0){ double sn=snapTimelineSample(sampleOfX((double)e.x)); int at=(int)std::lround(sn-(double)notes[idx].shift); if(proc.cutNote(idx,at)){ cutHoverIndex=-1; if(onSelectionChanged) onSelectionChanged(); } repaint(); } return; } if(idx<0){ if(!e.mods.isShiftDown()) proc.selectAll(false); if(onSelectionChanged) onSelectionChanged(); repaint(); return; } auto &hit=notes[idx]; if(e.mods.isShiftDown()) hit.selected=!hit.selected; else if(!hit.selected){ proc.selectAll(false); hit.selected=true; } if(onSelectionChanged) onSelectionChanged(); proc.pushUndo(); if(onBeginEdit) onBeginEdit(); initTarget.assign(notes.size(),0); initShift.assign(notes.size(),0); for(size_t i=0;i<notes.size();i++){ initTarget[i]=notes[i].targetMidi; initShift[i]=notes[i].shift; } downPos=e.getPosition(); dragging=true; repaint(); }
void PianoRoll::mouseDrag(const juce::MouseEvent& e){ if(!dragging) return; auto &notes=proc.getNotes(); if(initTarget.size()!=notes.size()) return; auto mask=proc.getScaleMask(); int N=proc.getNumSourceSamples(); if(tool==Tool::pitch){ double dy=-(double)(e.y-downPos.y)/rowH; for(size_t i=0;i<notes.size();i++){ if(!notes[i].selected) continue; if(std::abs(dy)<0.5){ notes[i].targetMidi=initTarget[i]; continue; } int m=(int)std::lround((double)initTarget[i]+dy); if(proc.lockScale) m=pauta::nearestInScale((float)m,mask); notes[i].targetMidi=(float)m; } } else if(tool==Tool::time){ double dx=(double)(e.x-downPos.x)/pps*sr(); for(size_t i=0;i<notes.size();i++){ auto &n=notes[i]; if(!n.selected) continue; double des=(double)n.start+(double)initShift[i]+dx; if(gridSeconds()>0) des=snapTimelineSample(des); double sh=des-(double)n.start; sh=juce::jlimit((double)-n.start,(double)(N-n.end),sh); n.shift=(int)std::lround(sh); } } proc.requestRender(); repaint(); }
void PianoRoll::mouseUp(const juce::MouseEvent&){ if(dragging){ dragging=false; proc.requestRender(); if(onSelectionChanged) onSelectionChanged(); repaint(); } }
void PianoRoll::mouseMove(const juce::MouseEvent& e){ if(tool!=Tool::cut) return; int idx=hitTest(e.position); int old=cutHoverIndex; double oldS=cutHoverSample; cutHoverIndex=idx; if(idx>=0) cutHoverSample=snapTimelineSample(sampleOfX((double)e.x)); if(old!=cutHoverIndex||oldS!=cutHoverSample) repaint(); }
void PianoRoll::mouseDoubleClick(const juce::MouseEvent& e){ if(tool!=Tool::pitch||!proc.hasProject()) return; int idx=hitTest(e.position); if(idx<0) return; proc.pushUndo(); auto &n=proc.getNotes()[idx]; n.targetMidi=(float)pauta::nearestInScale(n.targetMidi,proc.getScaleMask()); proc.requestRender(); repaint(); }
void PianoRoll::mouseWheelMove(const juce::MouseEvent& e,const juce::MouseWheelDetails& w){ if(e.mods.isCommandDown()||e.mods.isCtrlDown()){ if(w.deltaY!=0) setPixelsPerSecond(pps*(w.deltaY>0?1.18:1.0/1.18),(double)e.x); return; } double span=contentArea().getWidth()/pps; if(e.mods.isShiftDown()) scrollX-=(double)(w.deltaY!=0?w.deltaY:w.deltaX)*span*0.6; else { topMidi+=std::round((double)w.deltaY*10.0); scrollX-=(double)w.deltaX*span*0.6; } clampScroll(); updateScrollbars(); repaint(); }
bool PianoRoll::keyPressed(const juce::KeyPress& k){ if(k==juce::KeyPress('z',juce::ModifierKeys::commandModifier,0)){ proc.undo(); if(onSelectionChanged) onSelectionChanged(); repaint(); return true; } if(k==juce::KeyPress('a',juce::ModifierKeys::commandModifier,0)){ proc.selectAll(true); if(onSelectionChanged) onSelectionChanged(); repaint(); return true; } return false; }
